CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 1);
CREATE TABLE legal_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, name text NOT NULL, currency_code char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,name));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, email citext NOT NULL, display_name text NOT NULL, password_hash text NOT NULL, is_disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,email));
CREATE TABLE tenant_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, legal_entity_id uuid REFERENCES legal_entities(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,user_id));
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE RESTRICT, PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, PRIMARY KEY(tenant_id,user_id,role_id));
CREATE TABLE refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, replaced_by_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, line1 text NOT NULL, city text NOT NULL, postal_code text, country_code char(2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1);
CREATE TABLE clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1);
CREATE TABLE client_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, client_id uuid NOT NULL REFERENCES clients(id) ON DELETE RESTRICT, name text NOT NULL, email citext, phone text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1);
CREATE TABLE properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, client_id uuid NOT NULL REFERENCES clients(id) ON DELETE RESTRICT, address_id uuid NOT NULL REFERENCES addresses(id) ON DELETE RESTRICT, name text NOT NULL, property_type text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','under_maintenance','inactive','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1);
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, client_id uuid NOT NULL REFERENCES clients(id) ON DELETE RESTRICT, property_id uuid NOT NULL REFERENCES properties(id) ON DELETE RESTRICT, financial_owner_legal_entity_id uuid NOT NULL REFERENCES legal_entities(id) ON DELETE RESTRICT, project_manager_id uuid REFERENCES users(id) ON DELETE RESTRICT, project_number text NOT NULL, name text NOT NULL, description text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','planned','active','paused','completed','cancelled')), start_date date, expected_completion_date date, currency_code char(3) NOT NULL, estimated_budget numeric(19,4), approved_budget numeric(19,4), contract_value numeric(19,4), payment_status text NOT NULL DEFAULT 'not_required' CHECK(payment_status IN ('not_required','not_invoiced','partially_invoiced','invoiced','partially_paid','paid','overdue')), billing_customer_reference text, external_payment_customer_reference text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,project_number));
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, title text NOT NULL, description text, status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','blocked','completed','cancelled')), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), due_date date, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, CHECK((status='completed' AND completed_at IS NOT NULL) OR (status <> 'completed' AND completed_at IS NULL)));
CREATE TABLE task_assignments (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, assigned_at timestamptz NOT NULL DEFAULT now(), assigned_by uuid REFERENCES users(id) ON DELETE RESTRICT, PRIMARY KEY(task_id,user_id));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id) ON DELETE RESTRICT, actor_id uuid REFERENCES users(id) ON DELETE RESTRICT, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, correlation_id uuid NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_clients_tenant_active ON clients(tenant_id,updated_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_properties_tenant_client ON properties(tenant_id,client_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_projects_tenant_status ON projects(tenant_id,status,updated_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_tasks_tenant_project ON tasks(tenant_id,project_id,status) WHERE deleted_at IS NULL;
CREATE INDEX idx_audit_tenant_at ON audit_logs(tenant_id,occurred_at DESC);
ALTER TABLE projects ADD CONSTRAINT projects_amounts_nonnegative CHECK ((estimated_budget IS NULL OR estimated_budget >= 0) AND (approved_budget IS NULL OR approved_budget >= 0) AND (contract_value IS NULL OR contract_value >= 0));
ALTER TABLE projects ADD CONSTRAINT projects_version_positive CHECK (version > 0);
ALTER TABLE tasks ADD CONSTRAINT tasks_version_positive CHECK (version > 0);
-- Soft-deletable business and identity records retain the actor who archived them.
-- Permission bridges, assignments, tokens, audit events, and tenants are immutable/lifecycle records and do not use soft deletion.
ALTER TABLE legal_entities ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE users ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE tenant_memberships ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE roles ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE addresses ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE clients ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE client_contacts ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE properties ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE projects ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE tasks ADD COLUMN deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE properties ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_clients ON clients USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE POLICY tenant_properties ON properties USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE POLICY tenant_projects ON projects USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE POLICY tenant_tasks ON tasks USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
